def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        safe_bid = min(budget, DAILY_SALARY * 0.35)
        if hp <= 2 or no_water_days >= 1:
            safe_bid = min(budget, DAILY_SALARY * 0.75)
        return float(max(0.0, safe_bid))

    prev_bids = []
    opp_pressures = []
    needy_count = 0
    rich_count = 0
    for opp in alive:
        if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
            needy_count += 1
        if opp.get('budget', 0) >= 120:
            rich_count += 1
        prev = opp.get('previous_trace', {})
        bid = None
        if isinstance(prev, dict):
            bid = prev.get('bid')
        if bid is not None:
            prev_bids.append(float(bid))
            pressure = float(bid)
            if opp.get('hp', 0) <= 3 or opp.get('no_water_days', 0) >= 1:
                pressure += 8.0
            if opp.get('budget', 0) < 25:
                pressure -= 6.0
            opp_pressures.append(pressure)

    highest_prev = max(prev_bids) if prev_bids else 0.0
    highest_pressure = max(opp_pressures) if opp_pressures else highest_prev

    supply_factor = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY)
    if supply_factor < 0:
        supply_factor = 0.0
    if supply_factor > 1:
        supply_factor = 1.0

    my_urgent = 0
    if hp <= 2:
        my_urgent += 3
    elif hp <= 4:
        my_urgent += 2
    elif hp <= 6:
        my_urgent += 1
    if no_water_days >= 2:
        my_urgent += 3
    elif no_water_days >= 1:
        my_urgent += 2

    crowd = len(alive)
    base = DAILY_SALARY * (0.34 + 0.18 * (1.0 - supply_factor))
    base += 3.0 * crowd
    base += 4.0 * needy_count

    if my_urgent >= 4:
        bid = max(base, highest_pressure + 8.0, DAILY_SALARY * 0.95)
    elif my_urgent >= 2:
        bid = max(base, highest_pressure + 3.0, DAILY_SALARY * 0.72)
    else:
        if highest_prev >= DAILY_SALARY * 1.6 and supply <= 18:
            bid = DAILY_SALARY * 0.22
        elif highest_prev >= DAILY_SALARY * 1.2 and hp > 4 and no_water_days == 0:
            bid = DAILY_SALARY * 0.3
        else:
            bid = max(base, highest_pressure + 1.5)

    if supply >= 22:
        bid -= 6.0
    elif supply <= 17:
        bid += 7.0

    if rich_count >= 2 and my_urgent == 0 and highest_prev > 110:
        bid = min(bid, DAILY_SALARY * 0.38)

    if day >= 8:
        if hp <= 4 or no_water_days >= 1:
            bid = max(bid, DAILY_SALARY * 0.9)
        else:
            bid = max(bid, DAILY_SALARY * 0.55)

    if budget < DAILY_SALARY * 0.8:
        bid = min(bid, budget * 0.82)
    else:
        bid = min(bid, budget)

    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = day_context['day']

    my_hp = float(my_status['hp'])
    my_budget = float(my_status['budget'])
    my_no_water_days = int(my_status['no_water_days'])

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive', False):
            alive_opponents.append(opp)

    # If no opponents alive, bid conservatively.
    if not alive_opponents:
        return max(0.0, min(my_budget, DAILY_SALARY * 0.4))

    # Extract yesterday bids from previous_trace for immediate reaction.
    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict) and prev.get('bid') is not None:
            try:
                yesterday_bids.append(float(prev['bid']))
            except Exception:
                pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Base aggressiveness: higher when my HP is low or when supply is tight.
    supply_tightness = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_tightness = (MAX_SUPPLY - supply) / (MAX_SUPPLY - MIN_SUPPLY)
    supply_tightness = max(0.0, min(1.0, supply_tightness))

    hp_pressure = 0.0
    if my_hp <= 2:
        hp_pressure = 1.0
    elif my_hp <= 4:
        hp_pressure = 0.7
    elif my_hp <= 6:
        hp_pressure = 0.4
    else:
        hp_pressure = 0.2

    no_water_pressure = 0.0
    if my_no_water_days >= 2:
        no_water_pressure = 1.0
    elif my_no_water_days == 1:
        no_water_pressure = 0.5

    pressure = 0.55 * hp_pressure + 0.35 * no_water_pressure + 0.10 * supply_tightness

    # If someone previously bid extremely high, we must not get undercut.
    extreme_threshold = DAILY_SALARY * 0.85  # 76.5
    if highest_prev_bid >= extreme_threshold:
        target = DAILY_SALARY * (0.65 + 0.25 * pressure)
        # Slightly shadow the leader without matching exactly.
        target = max(target, min(my_budget, highest_prev_bid * 0.92))
    else:
        # Otherwise, bid enough to compete but preserve budget.
        target = DAILY_SALARY * (0.48 + 0.30 * pressure)
        # If my budget is low, cap target.
        target = min(target, DAILY_SALARY * 0.85)

    # Convert target into a safe bid: never exceed budget; keep non-negative.
    bid = max(0.0, min(my_budget, target))

    # If budget is extremely low, still bid a minimum to try to avoid starvation.
    if my_budget < 10.0:
        bid = max(0.0, min(my_budget, 8.0))

    return float(bid)

